const reviewNote='Walkthrough adapted from the linked community, illustrated and specialist guides, with AI-assisted source checks on 2026-10-02. Gameplay screenshots and reference sheets are credited to COD Zombies Guides and its listed contributors; Raven antiquity photographs are by Kristina Ebanez / Destructoid. Game imagery belongs to Activision / Treyarch. Select an image to enlarge it. This revision has not been verified in a full in-game run.'
export const guides=[
 {
  id:'bo6-citadelle-des-morts',gameId:'bo6',name:'Citadelle des Morts',reviewed:'2026-10-02',image:'/images/bo6-citadelle-des-morts/citadelle-des-morts.webp',reviewNote,
  intro:'Forge all four elemental swords, prepare their incantations and pass the knights’ trials to face the Guardian. This solo or co-op route includes every sword, the full bottle/book puzzle, boss preparation and the map’s substantial side quests. Use Standard mode for the full set of optional secrets. The visual helpers save your own match’s symbols; reference screenshots are examples, not fixed answers.',
  sources:[reddit('citadelle-des-morts'),illustrated('citadelle-des-morts'),'https://www.reddit.com/r/CODZombies/comments/1h7pcbf/','https://www.gamespot.com/gallery/bo6-zombies-how-to-complete-the-story-easter-egg-for-citadelle-des-morts/2900-6047/','https://raiderking.com/call-of-duty-black-ops-6-zombies-citadelle-des-morts-full-easter-egg-guide/','https://game8.co/games/Call-of-Duty-Black-Ops-6/archives/488171',side('citadelle-des-morts','rat-king'),side('citadelle-des-morts','wishing-well'),side('citadelle-des-morts','raven-free-perk'),'https://www.escapistmagazine.com/how-to-do-the-bartender-easter-egg-in-citadelle-des-morts-in-black-ops-6-zombies/','https://gameranx.com/features/id/520607/article/black-ops-6-zombies-citadelle-des-morts-chess-piece-easter-egg-guide/','https://game8.co/games/Call-of-Duty-Black-Ops-6/archives/493243','https://thegameslayer.com/guides/bell-tower-easter-egg-guide-citadelle-des-mortes/'],
  phases:[
   p('setup','Open the castle, Pack-a-Punch & Krafft',[
    s('castle-open','Buy a route from Town Square through the village to the castle Courtyard. Reach the rampart cannon, rotate it toward the castle entrance and fire to break the gates. Open the interior route through the Dining Hall and down to the Oubliette. Shoot the three crate locks, kill the released Doppelghast and collect its Blood Aetherium Crystal. Put the crystal into the crate’s portal to reveal Pack-a-Punch.','Cannon opens castle → Oubliette crate locks → Doppelghast crystal → Pack-a-Punch.'),
    s('castle-krafft','In the Dungeon, interact with the wooden door near Quick Revive to speak to Gabriel Krafft. Let his dialogue finish. The Alchemical Lab passage behind the Stag knight becomes accessible. Start collecting ritual items while saving essence for doors, armor, weapon upgrades and Melee Macchiato.','Speak to Krafft in Dungeon; open Alchemical Lab; prepare armor and Melee Macchiato.',{images:[c('krafft-wooden-door','Krafft’s wooden door in the Dungeon'),c('secret-room','Alchemical Lab passage behind the Stag knight')],note:'Every sword and incantation is required even in solo. Solo players exchange swords at their knight statues; you do not carry all four at once.'}),
    s('castle-stamps','From round 10, kill helmeted zombies and collect their Stamps. Body shots avoid their head protection. Spend one Stamp at each animal-marked knight in the Dining Hall to obtain its Bastard Sword. In co-op, assign one sword to each player; in solo, complete and return each sword before taking another.','Round 10 onward: four Stamps → Dragon, Stag, Raven and Lion swords.',{images:[c('stamp','A Stamp dropped by a helmeted zombie')],note:'Keep a reliable bullet weapon. The swords handle crowds, but precise shots are needed for puzzles and the Guardian’s exposed weak points.'})
   ],{group:'Key Features'}),
   p('dragon','Caliburn — Dragon’s Fire',[
    s('dragon-flames','Put the Dragon Bastard Sword into the dragon statue upstairs in Entrance Hall. Carry a flame from each brazier back to that statue, one at a time: ramparts beside the cannon; southeast corner of Town Square; Nature Path beside its Town Square gate. Interact with the dragon after every return.','Dragon statue → carry all three brazier flames home → collect Caliburn.',{bullets:['The flame damages you while carried and increases movement speed. Melee the glowing zombies on the return route to recover health.','Open your return route before taking a flame. If a delivery is lost, return to its brazier and retry; confirm which statue indicators remain unlit.'],images:[c('dragon-statue','Insert the Dragon sword here and return each carried flame'),c('village-rampart-brazier','Brazier on the ramparts beside the cannon'),c('town-square-brazier','Town Square brazier'),c('nature-path-brazier','Nature Path brazier by the Town Square gate')]})
   ],{group:'Main Quest'}),
   p('stag','Durendal — Stag of the Storms',[
    s('stag-rods','Collect the rod beside Deadshot Daiquiri at Hilltop. Shoot the electrical box near Speed Cola with a Dead Wire weapon, then pick up its rod. Take the Stag Bastard Sword into the Dungeon and kill the special rod-carrying zombie; use the sword for the kill to avoid ambiguity.','Rods: Deadshot ground pickup; Dead Wire box near Speed Cola; Dungeon zombie with Stag sword.',{images:[c('first-lightning-rod','Lightning rod beside Deadshot Daiquiri'),c('second-lightning-rod','Dead Wire this electrical box near Speed Cola'),c('final-lightning-rod','Dungeon zombie drops the third rod')]}),
    s('stag-storm','Insert all three rods into the metal vase on Hillside Ramparts. Stay inside the storm with the Stag sword drawn. Whenever lightning charges the blade, melee the vase to transfer the charge. Repeat three times, then interact to insert the sword and retrieve Durendal.','Storm vase: charge sword → melee vase, three times → insert sword → Durendal.',{images:[c('lightning-rod-vase','Place the rods and transfer three sword charges into this vase')],note:'Wait for visible electrical energy before striking. Ordinary melee hits with an uncharged blade do not complete a transfer.'})
   ]),
   p('raven','Balmung — Raven’s Shadow',[
    s('raven-trophy','Take the Raven Bastard Sword and collect the animal antiquity from a shelf or table in Alchemical Lab. Identify the actual object: ram horn, lion jaw, two-headed bird skull, fish fossil or scorpion fossil. At the Tavern Cellar wheel, insert the antiquity and sword.','Alchemical Lab antiquity + Raven sword → Tavern Cellar rune wheel.',{images:[c('lions-jaw-bone-trophy','Example antiquity: lion jaw; your match can use a different object')]}),
    s('raven-wheel','Use the visual helper to align the element on the inner ring and zodiac on the outer ring at the green bottom pointer. Horn = Fire/Aries; jaw = Fire/Leo; bird = Air/Gemini; fish = Water/Pisces; scorpion = Water/Scorpio. Confirm the alignment to release dark orbs.','Align the correct element and zodiac at six o’clock; confirm.',{note:'Fire is an upward triangle; Air adds a horizontal bar; Water points down. Distinguish the jaw from the paired bird skulls before turning the wheel.'}),
    s('raven-orbs','Stand beyond the floor portal so the chasing orbs pass through it. Feed three orbs into the cellar portal, then follow the portal’s two moves through the Tavern, finishing near the pool table. After the third portal is filled, follow the energy to the cellar wheel and interact to claim Balmung.','Guide three orbs into each of three portals → return to wheel → Balmung.',{images:[c('dark-portal','Lead the chasing dark orbs across each floor portal')],note:'The orbs damage you on contact. Keep circling through open floor space and let their route cross the portal; do not try to shoot them into it.'})
   ],{tools:['bo6-citadelle-raven']}),
   p('lion','Solais — Lion of Light',[
    s('lion-door','With the Lion Bastard Sword, melee a glowing gold Parasite to charge the blade. Strike the lion-knocker door at the bottom of the stairs near Speed Cola to transfer that charge. Repeat until all four door symbols glow, then interact to enter the passage.','Four gold Parasite melee charges → four strikes on the lion door → enter.',{images:[c('lion-door','The lion-knocker door near Speed Cola')],note:'Use the charged strike on the door before spending it on another enemy. Regular Parasites do not provide the required gold charge.'}),
    s('lion-pedestal','Insert the sword into the pedestal at the far end. Shoot the floating symbol that matches the currently illuminated pedestal symbol, then read the next one. Complete all four before the chamber’s timer ends and collect Solais.','Pedestal displays target → shoot matching floating symbol; repeat four times → Solais.',{images:[c('lion-pedestal','Read the lit pedestal symbol before each shot')],note:'Read the pedestal rather than trusting a remembered screenshot order. If the timer ejects you, return to the lion door on the following round and retry the chamber.'})
   ]),
   p('incantations','Four ritual items → four incantations',[
    s('incantation-rule','Krafft must have been spoken to before the rituals become available. Each item goes onto its matching glowing ritual circle. Kill enemies nearby until a gold chest appears, then melee that chest with the corresponding upgraded sword. Take its incantation into your tactical slot.','Item → correct ritual circle → nearby kills → matching sword opens chest.',{note:'You can prepare ritual items before finishing their swords. Incantation chests replenish after a cooldown, so return for another charge when needed.'}),
    s('incantation-fire','From the ramparts, ignite the three elevated wooden pyres: above the main castle gate, above the Elemental Pop-side doorway, and on the hill toward the village. Use Caliburn’s fire attack or Molotovs. Kill each wave and the final Doppelghast; take Ra’s Ankh to the Courtyard circle beside the Arsenal. Charge it and open its chest with Caliburn.','Light three high pyres → kill spawned enemies → Ankh to Courtyard → Fire Incantation.',{images:[c('first-wooden-pyre','Fire ritual pyre above the main castle gate'),c('second-wooden-pyre','Fire ritual pyre above the rampart doorway'),c('final-wooden-pyre','Fire ritual pyre overlooking the village'),c('fire-ritual-circle','Place Ra’s Ankh at this Courtyard ritual circle')]}),
    s('incantation-electric','Shoot Otto’s horseshoe above the far doorway inside the Hilltop stable, collect it and launch yourself toward Town Square using the rampart cannon. Look for the storm cloud over Nature Path or the village and collect the electrified Pegasus’ Horseshoe beneath it. Place it at the Town Square circle by the Nature Path gate, charge it and use Durendal to open the chest.','Stable horseshoe → ride cannon → retrieve horseshoe under storm cloud → Town Square ritual.',{images:[c('ottos-horseshoe','Shoot down this horseshoe inside the Hilltop stable'),c('electric-ritual','Town Square electric ritual beside the Nature Path route')]}),
    s('incantation-dark','Take the cave slide from the Pack-a-Punch area to Town Square. Shoot the perched raven near the slide’s end, then shoot it flying over the outside areas and collect its talon. Put the talon onto the Undercroft ritual circle near the Mystery Box and tombstones. Charge it, then open its chest with Balmung.','Shoot slide raven → shoot flying raven → talon to Undercroft ritual → Dark Incantation.',{images:[c('raven','Raven near the end of the cave slide'),c('dark-ritual','Raven’s Talon ritual in the Undercroft')],note:'For the optional raven perk, follow the living bird first; shoot it for the talon after it drops the perk. Missing the slide shot only means taking another trip.'}),
    s('incantation-light','Shoot the red crystal above Vulture Aid and adjust your firing angle until its beam reaches the next crystal. Continue along the beam through the Dining Hall crystals into Alchemical Lab, ending at the crystal above the Arsenal. Direct the last beam onto the stone bust on the lab table to reveal Paladin’s Brooch. Put the brooch on the Dining Hall circle near the Entrance Hall door, charge it and open the chest with Solais.','Align red crystal beams → collect brooch from lab bust → Dining Hall ritual → Light Incantation.',{images:[c('first-crystal','Start the beam at the crystal above Vulture Aid'),c('arsenal-crystal','Final crystal above the Alchemical Lab Arsenal'),c('paladins-brooch','Collect the brooch from the illuminated bust')],note:'If the beam will not align from your current position, move and fire from another angle. The solid connected beam confirms each link.'})
   ]),
   p('book','Tavern bottles, four pages & Point of Power traps',[
    s('bottles','Buy Melee Macchiato and punch the cracked square wall in Undercroft while holding a gun to expose twenty runes. In the Tavern, interact with all six small numbered bottles and record the rune for I, II, III, IV, V and VI in the helper. Return and shoot those runes in number order, waiting for the wall to settle between hits.','Melee Macchiato wall → record bottle runes I–VI → shoot matching sequence.',{bullets:['I: corner of the bar; II: table near the Arsenal; III: downstairs corner near the other end of the bar.','IV: upstairs near the pool table/dartboard; V: table opposite bottle II; VI: corner table near the left entrance.'],images:[c('symbol-vase','Interact with each bottle; its Roman numeral sets its order'),c('symbol-board','The rune wall rearranges after your shots')],note:'The bottle numbers are fixed; their runes change by match. A screenshot’s tile positions are not a solution for your wall.'}),
    s('book-pages','Collect four red-symbol page fragments in and immediately around Sitting Rooms: near the Entrance Hall doorway and boxes; around the bunk beds; around the TV/sofa; and in the corridor toward the Oubliette. Place all four into the revealed Undercroft book.','Four Sitting Rooms page fragments → restore the Undercroft book.',{images:[c('page-fragment','Look for the red glowing page fragments around Sitting Rooms'),c('book-pages','Read top left, bottom left, top right, bottom right')]}),
    s('book-traps','Match the book’s first symbol to a Point of Power floor trap. Activate it and get kills within its area until it shuts off early and that book symbol dims. Repeat in book order: top left, bottom left, top right, bottom right. Inspect traps in Village Ascent, Hilltop/Nature Path, Courtyard, Dungeon, Undercroft and Sitting Rooms; the last required trap is in Sitting Rooms.','Match and finish four traps in book order; confirm each page dims.',{note:'Two traps are fully illuminated decoys: match the exact eye/rays instead of choosing the brightest. If a page stays red, recheck its design and kill enemies inside the correct active circle. Do not mark success just because a normal trap timer ran out.'}),
    s('book-shortcut','Experienced alternative: before picking up pages, read their symbols in their spawn groups. Near Entrance Hall = first; bunk-bed group = second; TV/sofa group = third; corridor toward Oubliette = fourth. Complete the matching traps in that order without assembling the book. The full bottle/book route above remains the clearest first-run path.','Optional repeat-run shortcut: read page spawn groups before collecting them.',{images:[c('pages-puzzle-skip','Community reference for page spawn groups and their sequence')],note:'Do not mix a partially collected page route with guessed symbols. If you already picked pages up, finish the bottle puzzle and use the restored book.'})
   ],{tools:['bo6-citadelle-symbols']}),
   p('knights','Salute the knights & charge the Mystic Orb',[
    s('knights-salute','After the fourth trap, read the animal order I–IV around the orb recess on the stairs between Sitting Rooms and the lower castle. At each matching Dining Hall knight, equip its upgraded sword, cast its matching incantation at the statue, then immediately trigger the sword inspect animation. A successful knight salutes and glows. Finish all four in the displayed order and collect the lowered Mystic Orb.','Read I–IV animal order → matching sword + incantation + inspect → take Mystic Orb.',{images:[c('animal-symbol-wall','This match-specific animal order controls the knight salutes'),c('glowing-knight','A glowing, saluting knight confirms success')],bullets:['Dragon: Caliburn + Fire. Stag: Durendal + Electric.','Raven: Balmung + Dark. Lion: Solais + Light.'],note:'Inspect is the weapon-inspect action, not melee or interact. You only need to start its animation. If a knight does not react, verify the sword and tactical incantation before moving on.'}),
    s('orb-fire','Insert the orb into the Courtyard holder on the wall near the tree/trap and activate it. Kill enemies close to the orb with fire damage: Fire Incantation, Caliburn’s elemental attack, Molotovs or Napalm Burst. Retrieve the orb after the challenge confirms completion.','Courtyard orb: fire kills → retrieve charged orb.',{images:[c('fire-orb-pedestal','Courtyard holder for the fire trial')]}),
    s('orb-electric','Place and activate the orb in the Town Square holder by the Nature Path gate. Use Electric Incantation or Durendal’s elemental attack on nearby enemies until it completes, then take the orb back.','Town Square orb: electric kills → retrieve orb.',{images:[c('electric-orb-pedestal','Town Square holder for the electric trial')]}),
    s('orb-dark','At the Undercroft holder beside the Dark Incantation chest, activate the orb and collect shadow-damage kills with Dark Incantation or Balmung’s special attack. Retrieve it when its new elemental light appears.','Undercroft orb: shadow kills → retrieve orb.',{images:[c('dark-orb-pedestal','Undercroft holder for the shadow trial')]}),
    s('orb-light','Place the orb upstairs in Dining Hall above the Entrance Hall doorway, opposite Vulture Aid. Activate it and run through the green light orbs appearing throughout the room. Keep moving between upstairs and downstairs until enough have been absorbed; collect the Mystic Orb.','Dining Hall orb: run through green light orbs → retrieve completed orb.',{images:[c('light-orb-pedestal','Dining Hall balcony holder'),c('light-orb','Run through these green light orbs')],note:'These four trials do not reuse the knight-salute order. Confirm the orb has gained each element before returning it to the stairway recess. If a trial fails, reactivate its holder and repeat that trial.'})
   ]),
   p('guardian','Guardian key, arena preparation & boss',[
    s('guardian-key','Return the fully charged Mystic Orb to the animal-marked stairway recess. Enter the Secret Study, interact with the recording and wait for the Owl’s dialogue. Collect the Guardian Key. Before using it, fully upgrade a bullet weapon, refill armor/ammunition, buy survivability perks and prepare a self-revive and charged field upgrade.','Charged orb → Secret Study → recording → Guardian Key; resupply before committing.',{images:[c('guardian-key','Collect the Guardian Key from the Secret Study table')],note:'Solais is useful for armor recovery when charged. Carry Fire or Electric Incantation for the Amalgam between boss phases. Prepare the whole team before the final interaction.'}),
    s('guardian-start','Place the key into the eye-marked socket at the Town Square statue and accept the boss start. Keep moving around the arena. Shoot an armored section until it breaks, then focus the glowing weak point underneath. Change aim to another armored section if the exposed point stops taking useful damage.','Town Square statue key → break armor → focus glowing weak points.',{images:[c('boss-fight','The Town Square statue’s key socket begins the finale'),c('phase-1','Break the Guardian’s armor to expose glowing damage points')]}),
    s('guardian-survive','Move away from the fireball impact zones and the straight lava trail of the hammer slam. When a red circle marks a leaping strike, get out promptly; its knockback can throw you into lava. At health thresholds the Guardian becomes immune and enemy waves arrive. Clear those enemies, replace armor and gather drops before the next damage phase.','Avoid red landing circles and lava; use immune phases to clear enemies and resupply.',{images:[c('fireball-attack','Fireball impact areas leave dangerous lava'),c('leaping-hammer-attack','Move out of the telegraphed hammer landing area')],note:'The safe arena shrinks and the Guardian moves faster as the fight advances. Preserve an escape route rather than backing into the lava edge while aiming.'}),
    s('guardian-end','Repeat armor breaks and weak-point damage through all three phases. Use your field upgrade to recover space or secure damage while the team handles adds. Once the Guardian falls, collect the amulet to finish the quest and trigger the ending.','Defeat all three phases → collect amulet → ending.',{images:[c('amulet','Take the amulet after defeating the Guardian')]})
   ])
  ],
  sidePhases:[
   p('side-perks','Free perks — bartender, Peeks, raven & rune lockdown',[
    s('side-bartender','Collect the three liquor bottles: under a table near the red couch in Undercroft; beside the couch in Dining Hall; and on a shelf in Sitting Rooms. Go behind the Tavern bar and interact with the serving area/tray below the colored bottles. Serve each approaching zombie the drink matching its glow. Keep serving correctly until PhD Flopper is awarded.','Three liquor bottles → Tavern serving game → match drink colors → PhD Flopper.',{note:'These liquor bottles are separate from the six numbered puzzle bottles. Discard an unwanted drink in the bin behind the bar. A failed serving run can be attempted again after the game resets.'}),
    s('side-peeks','Shoot Peeks’ blue orb at four locations in this order: through the Elemental Pop room’s window; through the hole in the stable wall facing the castle; from the Dining Hall upper balcony toward the high tower window; then inside the Dungeon cell beside the ammo crate. Listen for his laugh at each hit; the last awards a random perk.','Peeks: Elemental Pop window → stable hole → Dining Hall high window → Dungeon cell.'),
    s('side-raven-perk','Release the raven with the cave-slide shot, then follow it outside while keeping it in view instead of killing it. After several laps, roughly three to four minutes, it drops a random perk near Nature Path. Collect the perk, then shoot the raven if you still need the talon for the Dark Incantation.','Follow the released raven alive for several laps → perk → shoot later for talon.',{images:[c('raven-free-perk','Following the living raven yields an optional perk before its quest talon')]}),
    s('side-wall','After completing the book/trap stage, cast each of the four different incantations onto the dimmed Undercroft rune wall. When all rows light again, survive its three-wave lockdown and collect the dropped reward loot, including a random perk and ammo mods.','Four incantations on dim rune wall → three-wave defense → reward loot.',{note:'Return with sufficient ammunition and incantation charges. This optional defense is a separate interaction from the main quest’s six-bottle code.'})
   ],{group:'Side Quests'}),
   p('rat-king','Rat King — cheese and all ten rats',[
    s('rats','Break the cheese shop window in Town Square beside the Tavern Cellar stairs and take the wheel. Approach each rat, crouching or going prone to make it flee. Once all ten have moved, place the cheese on the plate in the Oubliette near Pack-a-Punch. Collect the loot and crown.','Cheese shop wheel → scare ten rats → Oubliette plate → loot and Rat King crown.',{bullets:['Town Square: under a planter. Village Ascent: under the blockade vehicle. Nature Path / Hilltop: beside the zombie hole near Deadshot.','Ramparts: beneath the cannon stairs. Entrance Hall: under a chair near Dining Hall. Dining Hall: under a pallet near the Stag statue.','Dungeon: inside a jail cell. Alchemical Lab: behind the elemental slab under its table. Sitting Rooms: beneath the table near the bunk beds / Stamin-Up. Undercroft: beside the Mystery Box zombie spawn.'],note:'Feeding fewer rats can still give loot, but the crown needs all ten. Visit every hiding place before placing the cheese; only one player can wear the crown.'})
   ]),
   p('chess-fire','Chess guardian & fireplace protector',[
    s('chess','Find the white knight piece in one of four places: Tavern Cellar shelf; table opposite Elemental Pop; table in the upstairs Dining Hall Passage; or the Dungeon table near Quick Revive. Place it on the Sitting Rooms chessboard. Kill zombies within the purple zone until the spectral knight appears and follows you, crushing enemies for a limited time.','White knight piece → Sitting Rooms chessboard → kills in purple zone → temporary guardian.',{note:'Start with enough zombies available. The knight is a temporary attacker; it does not replace a self-revive or revive teammates.'}),
    s('fireplaces','Light the four fireplaces in quick succession with Molotovs or Caliburn: Tavern, Dining Hall, Alchemical Lab and Sitting Rooms. Open the whole route first and coordinate in co-op. Completing the chain releases fiery wisps that attack zombies. If the early fires go out, wait for the next attempt and repeat the full chain.','Rapidly light Tavern → Dining Hall → Lab → Sitting Rooms fireplaces for fire wisps.')
   ]),
   p('cannon-well','Cannon repair, bell tower & wishing well',[
    s('cannon-repair','After using the cannon to open the castle, retrieve the gear/crank from the fruit crate beneath the collapsed debris in Town Square. Take the blowtorch from Dining Hall beside the fireplace, behind the floor light. Install both at the cannon. You can now rotate it between the Town Square and Dining Hall travel routes.','Town Square fruit-crate gear + Dining Hall fireplace blowtorch → repair cannon.'),
    s('bell','For the novelty bell-tower secret, repeatedly use the repaired cannon’s Town Square route. On the hundredth launch it sends you into the bell tower, ringing the bell, attracting nearby zombies and dropping two Monkey Bombs. This is an expensive optional diversion, not a main-quest requirement.','Optional: 100 Town Square cannon rides → ringing bell and Monkey Bombs.'),
    s('well','During a Vermin round, wait by the Village Ascent well for a Vermin to crawl out. Throw a grenade into the well to release essence. After it is activated, hold interact to deposit essence, up to 10,000 between eligible Vermin rounds. Use a grenade during a later Vermin round to withdraw the stored essence as pickups any teammate can take.','Vermin emerges → grenade for essence → deposit at well → later Vermin round withdraw.',{images:[c('wishing-well','Village Ascent wishing well')],note:'Pickups benefit from an active Double Points. If the well is unresponsive, wait for the Vermin emergence/next eligible special round rather than throwing repeated grenades at an inactive well.'})
   ]),
   p('maya-music','Maya’s revenge, two songs & pool-table essence',[
    s('maya','Play as Maya. From round 12, interact with the radio beside the upstairs Dining Hall door. Once the conversation finishes, enter the private hallway, defeat the enemies and the named Doppelghast, take its key and unlock the final door for the story scene. Return to collect the legendary GS45 beside the radio.','Maya, round 12+ → upstairs Dining Hall radio → hallway fight → key/door → legendary GS45.',{note:'This sequence belongs to the Maya player. Upgrade and refill before entering the confined combat area.'}),
    s('song-slave','Interact with the three Mister Peeks headphones: on a Tavern table; in the Courtyard/east rampart corner near the weapon wall-buy; and beside the red couch in Undercroft. Activating all three plays “Slave.”','Headphones: Tavern table, Courtyard/east rampart corner, Undercroft couch → “Slave.”'),
    s('song-caliburn','After forging Caliburn, melee each of its original three braziers with the upgraded sword to light them again and replay the “Caliburn” music. Shoot the Tavern pool balls for a separate small essence reward.','Caliburn: relight its three braziers. Pool table: shoot the balls for 100 essence.')
   ]),
   p('powerups','All eight hidden power-ups',[
    s('powerup-targets','Shoot the tiny power-up models to spawn their full-size pickups near you. Save ammunition and armor drops for when you actually need them.','Shoot seven hidden models; the eighth Fire Sale then appears in the well.',{bullets:['Max Ammo: small window above the Village Ascent passage near Speed Cola. Insta-Kill: scaffolding above the Tavern/cave-slide exit, visible from the cellar stairs.','Max Armor: roof beam inside Entrance Hall above Jugger-Nog. Full Power: Dining Hall roof opposite Vulture Aid.','Double Points: through the Alchemical Lab zombie window beside the armor wall-buy. Bonus Points: behind the red Undercroft couch; go prone.','Nuke: high on the castle/Elemental Pop tower, sighted from Hilltop; an explosive can help reach it.','Fire Sale: inside the Village Ascent well after collecting the other seven hidden power-ups.']})
   ]),
   p('map-reference','Useful map services & travel',[
    s('services','Town Square/Tavern is your spawn-side Arsenal and crafting hub. Courtyard and Alchemical Lab have additional Arsenals. Jugger-Nog is in Entrance Hall, Vulture Aid in Dining Hall, Quick Revive in Dungeon, Stamin-Up in Sitting Rooms, Speed Cola in the village and Deadshot on the Nature Path/Hilltop route. The cannon and cave slide shorten trips between the castle and spawn.','Resupply at Tavern, Courtyard or Lab; cave slide and cannon connect castle to spawn.',{note:'Use the in-game map for current machine, ammo and box markers. Perk/weapon names are more reliable landmarks than a screenshot’s camera direction.'})
   ])
  ]
 },
 {
  id:'bo6-the-tomb',gameId:'bo6',name:'The Tomb',reviewed:'2026-10-02',image:'/images/bo6-the-tomb/the-tomb.webp',reviewNote,
  intro:'Build and upgrade the Staff of Ice, return four fragile trial charges and defeat the Sentinel Artifact. The full solo/co-op route below includes the real rock-glyph helper, both constellation puzzles, every statue trial and the map’s major side rewards. Use Standard mode for the full set of optional secrets. Bring a strong bullet weapon for the finale: the Staff and explosive weapons support survival, but do not replace accurate damage against the artifact.',
  sources:[reddit('the-tomb'),illustrated('the-tomb'),'https://www.reddit.com/r/CODZombies/comments/1icik6m/','https://gameranx.com/features/id/526510/article/black-ops-6-zombies-the-tomb-main-quest-easter-egg-guide/','https://www.gamespot.com/gallery/call-of-duty-black-ops-6-zombies-the-tomb-story-easter-egg-guide/2900-6181/','https://game8.co/games/Call-of-Duty-Black-Ops-6/archives/496019',side('the-tomb','golden-armor'),side('the-tomb','free-self-revive'),side('the-tomb','free-ray-gun'),side('the-tomb','aether'),'https://gameranx.com/features/id/526356/article/black-ops-6-zombies-all-shovel-locations-on-the-tomb/','https://game8.co/games/Call-of-Duty-Black-Ops-6/archives/495985','https://callofduty.fandom.com/wiki/The_Tomb','https://www.callofduty.com/guides/blackops6/zombies/call-of-duty-guides-black-ops-6-round-based-zombies-the-tomb'],
  phases:[
   p('nexus','Enter the Nexus & prepare for the Staff',[
    s('tomb-open','Follow either underground route from Dig Site to Subterranean Temple. Interact with the crystal pedestal at the marked Door to Nowhere to place the amulet and open the Dark Aether Nexus gateway. Enter the Nexus to find Pack-a-Punch and unlock the rest of the quest.','Dig Site → Subterranean Temple pedestal → open and enter Dark Aether Nexus.',{note:'You do not need a prior Citadelle completion on your account. The amulet interaction is part of this map’s setup.'}),
    s('tomb-prep','Buy armor and upgrade a dependable bullet weapon before beginning the Staff defenses. Pick up a shovel on your route for optional digging. Learn the Nexus portal links: blue to Dig Site, yellow to Shrine of the Hierophants, green to Ossuary and red to Subterranean Temple. Check map markers for Pack-a-Punch when it changes location between Nexus and Roman Mausoleum.','Prepare armor/bullet damage; learn blue spawn, yellow Shrine, green Ossuary and red Temple portals.',{note:'Use Standard mode for the full set of side quests. Keep the bullet weapon through the finale even if you also obtain the free Ray Gun.'})
   ],{group:'Key Features'}),
   p('staff','Monocle, two constellations & Staff defense',[
    s('staff-monocle','Kill the first Shock Mimic, normally on round 8, and pick up the Monocle it drops. You also need to have entered the Nexus. The Monocle lets you see the constellation symbols when the purple lantern is correctly positioned.','Round 8 Shock Mimic → collect Monocle; enter Nexus before puzzles.',{images:[t('monocle','Collect the Monocle from the first Shock Mimic')]}),
    s('staff-bull','In Tombs near Death Perception, move the purple Aetheric Lantern to the holder opposite the bull mural by shooting its current position. Wait for it to relocate before shooting again. With the mural illuminated, shoot its eight symbols in Roman-numeral order I → II → III → IV → V → VI → VII → VIII. Follow the purple orb’s combat stops and clear the five waves; collect the Staff piece at the mural.','Tombs lantern faces bull → shoot I–VIII → five-wave defense → Staff piece.',{images:[t('tombs-illuminated-symbols','Bull mural and illuminated numeral targets in Tombs'),t('staff-piece','Collect the Staff piece after the defense')],note:'IV is four, VI is six. The symbols are stylized Roman numerals, not random runes; identify the complete mark before firing.'}),
    s('staff-archer','In Neolithic Catacombs near Deadshot, shoot the purple lantern until it occupies the ceiling holder by the Crafting Table opposite the archer mural. Shoot all ten numerals in ascending order, I through X, then follow and finish its five combat waves. Pick up the Head Piece. Either constellation may be completed first.','Catacombs lantern by Crafting Table → shoot I–X → five-wave defense → Head Piece.',{images:[t('catacombs-lantern','Position the lantern in front of the Catacombs crafting area'),t('head-piece','Head Piece reward after the archer constellation defense')],note:'Lanterns take time to respawn at the next holder. Stop firing once your mural lights. On a wrong numeral, inspect what remains lit and resume the accepted sequence; if the challenge fully resets, start again at I.'}),
    s('staff-build','Bring the Monocle and both pieces to the central stone Staff altar in the Nexus. Interact to begin its defense. Prioritize the purple-eyed, smoking zombies that attack the forming Staff and the Parasites overhead; ordinary enemies can be trained while the objective attackers are removed. When the defense ends, claim the Staff of Ice.','Nexus central altar → protect forming Staff → collect Staff of Ice.',{images:[t('construct-staff','The central Nexus altar assembles the Staff')],note:'If its health is depleted, wait until the next round and retry at the altar. A Staff obtained from the Mystery Box skips construction, but still needs the upgrade quest below.'})
   ],{group:'Main Quest'}),
   p('upgrade','Ull’s Arrow — lantern sprint, three glyphs & escort',[
    s('upgrade-lanterns','Move three lanterns into convenient positions with a bullet weapon first. A useful route is Subterranean Temple → Ossuary → Neolithic Catacombs; the opposite Tombs → Shrine → Temple route also works. Then shoot one lantern in each of the three different areas with the Ice Staff within ten seconds. Archibald’s dialogue confirms the challenge.','Position three lanterns → freeze all three within ten seconds → listen for confirmation.',{images:[t('temple-lantern','Convenient Subterranean Temple lantern position'),t('ossuary-lantern','Convenient Ossuary lantern position'),t('catacombs-lantern','Convenient Catacombs lantern position')],note:'Repositioning and freezing are different actions: bullets move lanterns, Staff shots freeze them. Rehearse the run before starting the timer; if it fails, reset the positions and retry.'}),
    s('upgrade-rocks','Return to the Nexus and look up for the three floating rocks bearing purple glyphs. Shoot each marked rock with the Ice Staff to lower it. Record the three exact shapes in the helper below. Only three of the eight possible rocks are marked in a match.','Staff-shoot three marked Nexus rocks; record all three glyphs.',{images:[t('symbol-rock','Lower the marked rock with the Staff to read its glyph clearly')]}),
    s('upgrade-door','Leave through an open gateway, then find the closed gateway on the excavation side. Shoot the three glyphs matching your rocks with the Ice Staff; order does not matter. Check for the successful symbols on the ground below the gateway before entering. A correct door leads to a floating platform with a purple orb.','Outside Nexus: find blocked gateway → shoot your three glyphs → check ground symbols.',{images:[t('blocked-door-with-symbols','The blocked gateway presents eight possible glyphs')],note:'A door can reopen after incorrect input and drop you when entered. Do not treat “open” as confirmation. A failed input requires another attempt at the newly closed gateway on the next round.'}),
    s('upgrade-escort','Gather every player and activate the purple orb on the platform. Follow it closely around the Nexus while killing enemies near it. Do not split up for errands: any player falling behind can fail the escort. Once it returns to the central altar, interact there with the Staff to upgrade it into Ull’s Arrow.','All players follow and feed the orb → central altar interaction → Ull’s Arrow.',{images:[t('purple-orb','Interact with the purple orb on the safe platform'),t('ulls-arrow','Interact at the Staff altar after the escort to receive Ull’s Arrow')],note:'On failure, advance a round, find the newly blocked gateway and repeat its glyph entry and escort. Completed Staff construction does not need to be repeated.'})
   ],{tools:['bo6-tomb-symbols']}),
   p('trials','The four statue trials & fragile return charges',[
    s('trials-rule','Toggle Ull’s Arrow to Sekhmet’s Vigor, its revive/healing shot. Shoot the crystal on the next creature statue in the Nexus, collect the released energy and place it in that creature’s matching statue outside. Complete the trial, pick the refined charge back up and return it to the original Nexus statue. Follow Vermin → Parasite → Doppelghast → Amalgam.','Healing shot on Nexus statue → matching outside trial → carry charge back → deposit.',{note:'These interactions do not advance during special enemy rounds. The return energy has its own meter and can be lost after very few hits. Only one gateway remains available on return; identify that exit before lifting the charge, and have teammates clear the route.'}),
    s('trial-vermin','Release the Vermin energy from the Nexus statue near the central altar and take it to the Dig Site Vermin statue. Start its timed defense and kill the Vermin; charged Staff shots cover the floor well. Collect the refined energy and return through the available portal to the Nexus Vermin statue.','Vermin: Nexus → Dig Site defense → safe return → Nexus Vermin deposit.',{images:[t('aether-vermin-statue','Nexus Vermin statue: use the healing shot on its crystal'),t('vermin-statue','Dig Site Vermin statue for the outside defense')]}),
    s('trial-parasite','Take Parasite energy from its Nexus statue to the matching Shrine of the Hierophants statue. During the timed trial, shoot the purple-glowing Parasites, collect their dropped energy orbs and carry those orbs into the statue. Kills alone do not fill it. When complete, collect the refined charge and return it to the Nexus Parasite statue.','Parasite: Shrine trial → kill purple Parasites, collect and deposit orbs → return charge.',{images:[t('parasite-statue','Shrine of the Hierophants Parasite statue'),t('parasite-orb','Collect the dropped Parasite energy and deposit it')]}),
    s('trial-doppelghast','Activate the Nexus Doppelghast statue and carry its energy to the Ossuary counterpart. Kill the spawned Doppelghasts while avoiding the marked ground circles that erupt into spikes. Collect the refined charge only when you are ready to move and deliver it to the original Nexus statue.','Doppelghast: Ossuary defense; avoid spike circles → carry charge home.',{images:[t('doppleghast-statue','Ossuary Doppelghast statue')]}),
    s('trial-amalgam','Carry the final energy to the Amalgam statue in Deep Excavation, near the Subterranean Temple area. Damage the HVT Amalgam. When it shields itself, kill the zombies linked to it by energy tethers, then resume shooting the Amalgam. Defeat it and return the refined charge to the Nexus Amalgam statue.','Amalgam: Deep Excavation; kill shield-tether zombies → finish HVT → return charge.',{images:[t('amalgam-statue','Deep Excavation Amalgam statue')]}),
    s('trials-retry','If you lose a refined charge on the return route, go back to its outside statue and collect another charge; you do not need to replay a successfully completed defense. Use decoys, Staff crowd control and a ready movement/defensive field upgrade before carrying it. Confirm the Nexus statue accepts each deposit and its beam activates.','Lost return charge? Recollect at outside statue and retry delivery; confirm each beam.',{note:'Do not count a completed outside fight as a finished statue. The return deposit is a separate required action.'})
   ]),
   p('sentinel','Sentinel Artifact — damage windows, HVTs & final burst',[
    s('sentinel-prep','After all four deposits, activate the Nexus pedestal that forms the bridge to the boss arena. Before starting, reach legendary rarity and Pack-a-Punch III on your bullet weapon, refill ammunition and armor, buy core perks and prepare a self-revive and charged Aether Shroud or other survival field upgrade. The Staff handles adds; the bullet weapon damages the artifact.','Four statue beams → bridge; prepare PaP III legendary bullet weapon and survival supplies.',{images:[t('pedestal','Activate the bridge pedestal after all four statue charges'),t('boss-fight','Interact in the arena only after everyone is ready')],note:'Ray Gun explosions, explosive PaP weapons and Staff attacks are poor substitutes for the required bullet damage. Bring a weapon with a usable magazine and reload speed for the short vulnerability windows.'}),
    s('sentinel-beams','Start the fight at the Sentinel Artifact. While it glows orange and sweeps lasers, evade and clear space. When it stops and glows purple, immediately focus bullet fire on it. As it splits into multiple artifacts, repeat the same cycle; move between levels and use the arena’s geometry to avoid crossing active beams.','Orange/spinning = evade. Purple/stationary = focus bullet damage.',{images:[t('boss-attack','Avoid the sweeping orange beams'),t('phase-1','Shoot during the purple vulnerability window')],note:'Keep your magazine ready as the beams stop. Use crowd control before the window opens so zombies do not force you to waste the opening.'}),
    s('sentinel-hvts','Later waves attach the real orange artifact to an empowered enemy: first a heavy zombie, then a Doppelghast, Shock Mimic and Amalgam. Focus the carrier of the orange artifact; later duplicate carriers can have a pale decoy. Kill the correct HVT, then shoot the exposed artifact it drops during the brief damage opportunity.','Kill the orange-artifact carrier → shoot dropped artifact; ignore the pale decoy.',{images:[t('phase-3-artifact','An empowered enemy carries the target artifact'),t('phase-6-artifact','The Amalgam carrier is a major late-fight threat')],note:'HVT melee damage is severe. Slow and separate enemies with Staff shots, keep moving, and spend defensive resources before you get cornered. Collect the Max Ammo rewards between successful stages.'}),
    s('sentinel-finish','At the final low-health sequence, listen for the bell and find the artifact moving to the back wall. Immediately unload your bullet weapon into it until the final health is gone. This is a damage check: delaying until the wipe attack finishes can end the run. Interact with the artifact when prompted after the victory to finish the ending.','Final bell → shoot artifact at back wall immediately → finish health bar → ending.',{images:[t('phase-6','Locate the final artifact at the back of the arena and finish its damage check')],note:'Save a full magazine, ammunition and a damage/survival window for this finish. The game’s actual glow and carrier transitions are more useful than guide phase numbers, which different sources group differently.'})
   ])
  ],
  sidePhases:[
   p('gold-armor','Golden Armor — both Blood Sacrifices',[
    s('armor-heads','Melee open two wooden boxes in the Nexus: one beside Jugger-Nog and one beside the green gateway. Collect both stone heads, then return them to the headless statues in the Dig Site area: near PhD Flopper and in Roman Mausoleum near the blue gateway.','Two Nexus crates → heads onto Dig Site / Mausoleum statues.',{images:[t('golden-armor-first-wooden-box','Statue-head crate beside Jugger-Nog'),t('golden-armor-second-wooden-box','Statue-head crate beside the green Nexus gateway'),t('golden-armor-first-statue','Mausoleum statue near the blue gateway'),t('golden-armor-second-statue','Dig Site statue near PhD Flopper')]}),
    s('armor-sacrifice','Prepare upgraded weapons, full armor and a defensive field upgrade. Activate one restored statue to start its Blood Sacrifice: your health is reduced to one and scorestreaks are disabled. The Mausoleum/blue-gateway statue summons three HVT Doppelghasts; the PhD-side statue summons three HVT Shock Mimics. Defeat the full group, resupply, then complete the other statue.','One-health fights: Mausoleum Doppelghasts and PhD-side Shock Mimics; complete both.',{note:'Use the upgraded Staff to slow enemies and create firing space. If survival collapses, leave the ritual area to cancel it and recover before retrying. Do not rely on old pre-activation Mutant Injection exploits.'}),
    s('armor-buy','After both sacrifices, claim the free Golden Armor wall-buy at Roman Mausoleum near the bull statues. Every player can collect it. Its plates regenerate over time after avoiding damage, making it valuable for long runs and the boss.','Both sacrifices complete → free Golden Armor wall-buy for each player.',{images:[t('golden-armor','Golden Armor wall-buy in Roman Mausoleum')],note:'It is optional and its acquisition fights are dangerous. A first main-quest attempt can use ordinary fully upgraded armor instead.'})
   ],{group:'Side Quests'}),
   p('digging','All four shovels, dig loot & free Ray Gun',[
    s('shovels','Hold interact on one shovel; each player needs their own. Check the broken pillar beside the Tombs stairs, the Ossuary skull pile between its two rooms, the ledge left of the central waterfall arch in Subterranean Temple/Deep Excavation, and the ground right of Quick Revive.','Shovels: Tombs pillar; Ossuary skull pile; central waterfall arch; right of Quick Revive.',{note:'Dig the mounds of dirt, skulls and bones for loot. Depleted piles return after later rounds; shovel ownership alone does not guarantee a gem.'}),
    s('raygun','With Death Perception active, dig until you collect three Ancient Gems. Offer all three to the ancient statue beside the bull mural in Tombs, near Death Perception. Kill every Doppelghast it summons and wait for the reward animation, then take the free Ray Gun and essence.','Death Perception + shovel → three Ancient Gems → bull-mural statue → defeat Doppelghasts.',{images:[t('free-ray-gun-dig-spot','Look for a bone-and-dirt dig mound'),t('free-ray-gun-ancient-gem','Collect three of these Ancient Gems'),t('free-ray-gun-ancient-statue','Offer the gems to the statue beside the Tombs bull mural')],note:'The Ray Gun is useful for survival. Keep a separate strong bullet weapon for the Sentinel Artifact’s damage windows.'})
   ]),
   p('vases','Ten vases — free Self-Revive & Light Mend',[
    s('vases-rule','Shoot all ten small quest vases. The final vase releases a Self-Revive Kit and Light Mend ammo-mod reward. Use a precise bullet weapon for the high ledges and follow the photographed locations below.','Break all ten photographed vases → collect Self-Revive and Light Mend.'),
    ...tombVases.map((row,i)=>s(`tomb-vase-${i}`,`${row.room}: ${row.landmark}. Aim at the small vase on the pictured ledge; ordinary decorative pots do not count.`,`${i+1}/10 · ${row.room}: ${row.landmark}.`,{images:[{src:row.image,alt:`Vase ${i+1}: ${row.room} — ${row.landmark}`}]}))
   ]),
   p('free-upgrades','Free rarity tool, Pack-a-Punch crystal & ammo mods',[
    s('waterfalls','Use Cryofreeze or the Staff of Ice to freeze both waterfalls in the Nexus. Collect the Aether Tool in the central ruined structure. The reward improves with the round: rare before round 11, epic from 11–20 and legendary from 21 onward.','Freeze both Nexus waterfalls → rarity tool; wait to round 11/21 for a better tier.'),
    s('floating-rock','Find the small sparking rock circling the Nexus and shoot it. Rapidly shoot the additional rocks that appear around the area until the challenge finishes. Collect the Raw Aetherium Crystal at the central altar and the Cryofreeze mod drops. This rock challenge is separate from the three marked upgrade rocks.','Shoot sparking Nexus rock → quickly hit all spawned rocks → PaP crystal and Cryofreeze.'),
    s('brainrot','In Tombs, find the alcove with nine upright statues and one fallen statue. Shoot the fallen one to begin a memory sequence. Watch the heads light up; only after the display ends, shoot the upright heads in the same order. Collect the loot and Brain Rot mod.','Fallen statue starts Simon Says → repeat nine-statue light order → Brain Rot and loot.',{note:'Number the grid positions in your own notes before starting if needed. Watch the complete sequence; random shooting can reset the attempt.'}),
    s('ossuary-perk','In the Speed Cola room of Ossuary, ignite all six stone braziers, two by each entrance. Use Napalm Burst bullets or Molotovs; lit braziers drop replacement Molotovs. Once all six burn, collect the random perk in the room.','Ossuary: light six entrance braziers → random perk.'),
    s('generators','Equip Dead Wire and shoot both Dig Site generators. Collect the Full Power, armor and essence rewards on the fallen column. For renewable minor loot, melee the Nexus fungi to release insects, then shoot the insects; simply shooting the fungi mainly yields salvage.','Dead Wire both Dig Site generators; melee Nexus fungi and shoot insects for extra loot.')
   ]),
   p('tomb-secrets','Zombie soldiers, jumpscare & two songs',[
    s('soldiers','With Brain Rot equipped, quickly shoot the four X-marked skulls in Ossuary in this order: low on the north wall by the sacrificial-table room; floor between its spike traps; floor beside the green gateway; then the skull pile at the Doppelghast statue. This triggers the undead soldier event and releases the “Potts and Pains Pt 4” intel.','Brain Rot four X skulls: north wall → trap floor → green gateway → statue skull pile.'),
    s('jumpscare','Aim at the distant woman statue until it turns toward you with red eyes. Check above Quick Revive on the tall rock pillar, outside the Deadshot room’s zombie window, and beyond the Catacombs Mystery Box window. Whispering signals that the later sudden face/scream effect has been triggered.','Optional jumpscare: stare at the distant woman statue until its eyes turn red.',{note:'This is a cosmetic scare, not a required quest step or a guaranteed loot reward.'}),
    s('dig-song','Interact with the three Peeks headphones: Shrine of the Hierophants below the ledge left of Stamin-Up; Ossuary on a ledge beside the stairs toward the green gateway; Nexus along the southeast outer edge beside the glowing plant. All three activate “Dig.”','Headphones: Shrine, Ossuary, southeast Nexus → “Dig.”'),
    s('aether-song','After obtaining the Staff, rapidly shoot I, I, V on the Tombs bull mural and repeat I, I, V on the Catacombs archer mural. Completing both plays “Aether — The Tomb Mix.”','After Staff: shoot 1, 1, 5 on both constellation murals → “Aether.”')
   ]),
   p('tomb-powerups','All eight hidden power-ups',[
    s('tomb-powerup-targets','Shoot each miniature model to call its power-up to your position. The Fire Sale appears only after the seven other hidden rewards are collected.','Find seven hidden power-up models; collect them to unlock the Dig Site Fire Sale.',{bullets:['Bonus Points: small wall hole left of the blue Nexus gateway. Double Points: Nexus trench between the red and green gateways, above the mushroom opposite the ammo cache.','Full Power: opening left of the Shrine Crafting Table. Max Ammo: ledge above the floodlight at the Shrine–Temple arrow-trap passage.','Max Armor: wall alcove right of Speed Cola in Ossuary. Nuke: distant rock behind the Catacombs Mystery Box position.','Insta-Kill: distant Deep Excavation rock formation, below/right of the vase. Fire Sale: fire above the red light between PhD Flopper and the Rampage Inducer in Dig Site.']})
   ]),
   p('tomb-services','Map services & travel reminders',[
    s('tomb-map','Dig Site and Deep Excavation contain Arsenals; Dig Site sells a two-plate vest and Deep Excavation a three-plate vest. Perks: PhD at Dig Site, Death Perception in Tombs, Stamin-Up in Shrine, Deadshot in Catacombs, Speed Cola in Ossuary, Quick Revive in Deep Excavation and Jugger-Nog in Nexus. Portals are the quickest way across the excavation once all routes are open.','Use Dig Site/Deep Excavation Arsenals and Nexus portals to shorten resupply trips.',{note:'During trial returns, normal portal access changes. Follow the portal actually left open for the charge rather than assuming your usual shortcut still works.'})
   ])
  ]
 }
]
const f=(id,label,options=null,extra={})=>({id,label,options,...extra})
const check=(id,label)=>f(id,label,null,{type:'check'})
const tool=(id,map,name,help,fields,extra={})=>({id,map,name,help,fields,version:1,kind:'recorder',...extra})
export const tools=[
 // Legacy completion fields stay in the schema to preserve saved data; the visual tools no longer display or change them.
 tool('bo6-citadelle-raven','bo6-citadelle-des-morts','Raven sword — visual ring solution','Choose your actual antiquity and see the exact element and zodiac images to align at the bottom pointer.',[f('trophy','Antiquity',ravenTrophies.map(row=>row.id)),...Array.from({length:3},(_,i)=>check(`portal-${i}`,`Portal ${i+1} complete`))],{custom:true,kind:'solver',reference:reddit('citadelle-des-morts')}),
 tool('bo6-citadelle-symbols','bo6-citadelle-des-morts','Tavern runes & book trap sequence','Record six bottle runes using actual screenshot glyphs. Switch to four book pages to match trap eyes and save their observed locations.',[f('mode','Puzzle stage',['vases','traps']),f('vase-active','Selected bottle',['0','1','2','3','4','5']),f('page-active','Selected page',['0','1','2','3']),...Array.from({length:6},(_,i)=>f(`vase-${i}`,`Bottle ${i+1}`,castleRunes.map(row=>row.id))),...Array.from({length:4},(_,i)=>f(`page-${i}`,`Page ${i+1}`,trapEyes.map(row=>row.id))),...Array.from({length:4},(_,i)=>f(`location-${i}`,`Trap ${i+1}`,trapLocations)),...Array.from({length:6},(_,i)=>check(`vase-done-${i}`,`Rune ${i+1} accepted`)),...Array.from({length:4},(_,i)=>check(`page-done-${i}`,`Page ${i+1} dimmed`))],{custom:true,kind:'recorder',reference:reddit('citadelle-des-morts')}),
 tool('bo6-tomb-symbols','bo6-the-tomb','Ice Staff — rock glyphs to gateway','Select the three photographed rock glyphs in your match. See the matching gateway positions, verify the safe entrance and keep the escort instructions close.',tombRockSymbols.map(row=>check(row.id,row.label)),{custom:true,kind:'solver',reference:illustrated('the-tomb')})
]
